{
"shot": {
"composition": "Wide establishing shot using a 24mm anamorphic lens on ARRI Alexa 65, deep depth of field, subject centered in lower third with vast misty landscape dominating the frame",
"camera_motion": "Slow, smooth dolly forward combined with gentle upward crane lift, transitioning to subtle orbiting arc around the subject during the peak of the sword flourish",
"frame_rate": "24fps cinematic",
"film_grain": "Subtle natural 35mm Kodak Vision3 500T film grain emulation, light halation on highlights"
},
"subject": {
"description": "25-year-old East Asian woman of Chinese descent, long straight jet-black hair flowing freely with a single white silk ribbon, slender yet toned physique, porcelain skin, sharp yet serene almond-shaped eyes, calm and focused expression conveying inner strength",
"wardrobe": "Elegant pale azure hanfu with layered flowing sleeves, intricate silver-thread crane embroidery on the outer robe, wide white belt cinched at the waist, traditional jade hairpin and subtle natural makeup emphasizing graceful features"
},
"scene": {
"location": "Remote misty mountain lake shore surrounded by ancient pine and bamboo groves, inspired by classical Chinese ink painting landscapes",
"time_of_day": "Pre-dawn twilight transitioning to early sunrise",
"environment": "Thick rolling fog hugging the still lake surface, distant jagged mountain peaks faintly silhouetted, soft dew on reeds and rocks, occasional gentle ripples breaking the mirror-like water"
},
"visual_details": {
"action": "The woman stands motionless at first, eyes closed in meditation; she slowly raises her arms, draws a slender straight sword from behind her back in one fluid motion, begins a graceful yet powerful sword dance—slow deliberate spins, precise cuts through the air, hair and sleeves billowing dramatically, culminating in a dramatic flourish where the sword arcs overhead as the first rays of sun pierce the fog",
"props": "A single elegant straight sword (jian) with polished silver blade and dark wood hilt wrapped in red silk cord"
},
"cinematography": {
"lighting": "Soft, diffused pre-dawn ambient light with gentle blue-gray tones gradually giving way to warm golden sunrise rays piercing through the fog, creating strong rim light and subtle god rays around the subject",
"tone": "Mystical, serene yet powerfully empowering, meditative grace combined with quiet intensity"
},
"color_palette": "Dominant cool desaturated blues and soft grays of fog and twilight water, contrasted by emerging warm golden-orange sunrise highlights, subtle emerald greens from distant bamboo, delicate silver-white accents on clothing and sword"
}
