{
"shot": {
"composition": "广角建立镜头，使用24mm变形镜头在ARRI Alexa 65上拍摄，深景深，主体置于画面下三分之一位置，广阔雾气山湖景观占据主要画面",
"camera_motion": "缓慢平稳的推轨前进结合轻柔向上吊臂升格，在剑舞高潮时过渡为围绕主体的微妙环绕弧线运动",
"frame_rate": "24fps 电影标准帧率",
"film_grain": "轻微自然的35mm Kodak Vision3 500T胶片颗粒模拟，高光处带有轻微晕影效果"
},
"subject": {
"description": "25岁中国东亚女性，长直乌黑长发自由飘散，用一条白色丝带轻轻束起，身材纤细却结实匀称，瓷白肌肤，锐利而宁静的杏仁眼，表情平静专注，传递内在力量",
"wardrobe": "优雅淡青色汉服，多层宽袖飘逸，外袍绣有精致银线仙鹤图案，腰间系宽白腰带，传统玉簪点缀，发髻简洁，妆容自然突出优雅气质"
},
"scene": {
"location": "偏远雾气笼罩的山间湖岸，四周环绕古老松竹林，灵感来源于中国古典水墨山水画",
"time_of_day": "黎明前暮色渐转初升朝霞",
"environment": "浓厚雾气紧贴平静湖面翻滚，远方嶙峋山峰隐约剪影，芦苇与岩石上凝结柔软露珠，偶尔有轻微涟漪打破镜面般的水面"
},
"visual_details": {
"action": "女子起初静立闭目冥想，缓缓抬起双臂，从背后流畅拔出一柄细长直剑，开始优雅而有力的剑舞——缓慢而精准的旋转、空气中的利落斩击，发丝与衣袖剧烈飘扬，高潮时剑身高高弧起过头顶，第一缕晨曦恰好穿透雾气照亮她",
"props": "一柄优雅细长直剑（剑），银亮剑刃，深色木质剑柄缠绕红色丝绳"
},
"cinematography": {
"lighting": "柔和的黎明前环境光，蓝灰色调逐渐被穿透雾气的温暖金色朝霞取代，在主体身上形成强烈边缘光与细腻神光",
"tone": "神秘、宁静却充满力量的赋能感，冥想般的优雅与内在张力并存"
},
"color_palette": "主导冷调去饱和蓝灰雾色与暮色湖水，渐现温暖金橙朝霞高光，对比远方竹林的幽绿，服装与剑身上的银白细腻反光"
}
